<article class="da-adventure-card" data-adventure data-category="{{ $adventure['category'] }}" data-time="{{ $adventure['time'] }}" data-location="{{ $adventure['location'] }}" data-vehicle="{{ $adventure['vehicle'] }}" data-price="{{ $adventure['price'] }}" data-title="{{ strtolower($adventure['title']) }}">
    <div class="da-card-image"><img src="{{ asset($adventure['image']) }}" alt="{{ $adventure['title'] }}" loading="lazy"><span>Popular</span></div>
    <div class="da-card-content"><span class="da-card-category">{{ ['safari' => 'Desert safari', 'experience' => 'Desert experience', 'buggy' => 'Dune buggy', 'school' => 'School trip'][$adventure['category']] ?? 'Desert experience' }}</span><h3>{{ $adventure['title'] }}</h3><p>{{ $adventure['description'] }}</p><div class="da-card-tags"><b>{{ $adventure['badge'] }}</b><span>✓ Instant confirmation</span><span>♙ 4x4</span></div><div class="da-card-bottom"><small>Sample from <strong>AED {{ number_format($adventure['price']) }}</strong> per person</small><a href="{{ isset($adventure['route']) ? route($adventure['route']) : (isset($adventure['url']) ? url($adventure['url']) : '#') }}" class="da-book-button">View details <span aria-hidden="true">→</span></a></div></div>
</article>
